package mz.bam.seeky.android;
import android.app.*;import java.io.*;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.annotation.*;import static org.junit.Assert.*;

@RunWith(org.robolectric.RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class Summary513Test {
    WorkTestSupport w;SummaryWork.Clients originalClients;SummaryWork.Vaults originalVaults;int requests;
    @Before public void before()throws Exception{w=new WorkTestSupport();originalClients=SummaryWork.clients;originalVaults=SummaryWork.vaults;SummaryWork.vaults=c->new SeekyAiVault(c){synchronized String get(String provider){return "fixture-summary-credential";}};w.app.getSharedPreferences("seeky_ai",0).edit().putBoolean("configured_gemini",true).putBoolean("terms_gemini",true).apply();SummaryWork.clients=()->new SeekyAiClient((provider,key,payload,call)->{requests++;return reply("Resumo "+requests+" com origem [T1].");});}
    @After public void close(){SummaryWork.clients=originalClients;SummaryWork.vaults=originalVaults;w.close();}
    static String reply(String answer)throws Exception{return new JSONObject().put("candidates",new JSONArray().put(new JSONObject().put("finishReason","STOP").put("content",new JSONObject().put("parts",new JSONArray().put(new JSONObject().put("text",answer)))))).toString();}
    String job(int allowance,int paragraphs)throws Exception{StringBuilder text=new StringBuilder();for(int i=0;i<paragraphs;i++)text.append("Parágrafo ").append(i).append(": uma explicação para resumir com conceitos e fontes.\n\n");long material=w.book("Estudo.txt",text.toString());return w.job("summary",new JSONObject().put("uri",StudyFileProvider.uri(w.app,material).toString()).put("name","Estudo.txt").put("title","Estudo").put("mime","text/plain").put("material",material).put("first",0).put("last",0).put("prepared_part",0).put("requests",allowance));}
    @Test public void eachRunHonoursItsRequestAllowanceAndRetainsCompletedExcerpts()throws Exception{String id=job(2,700);try{w.run(id);fail();}catch(InterruptedIOException expected){}assertEquals(2,requests);assertEquals(2,w.items(id,"done"));long remaining=w.items(id,"pending");assertTrue(remaining>0);String first;try(TaskStore db=new TaskStore(w.app)){first=db.items(id,"done",0,1).get(0).s("message");}try{w.run(id);}catch(InterruptedIOException expected){}assertTrue(requests<=4);try(TaskStore db=new TaskStore(w.app)){assertEquals(first,db.items(id,"done",0,1).get(0).s("message"));}try(StudyStore notes=new StudyStore(w.app)){assertEquals(w.items(id,"done"),notes.count("notes",null,null));}}
    @Test public void interruptedRequestIsNotRepeatedWithoutChoosingThatExcerpt()throws Exception{String id=job(1,2);SummaryWork.clients=()->new SeekyAiClient((p,k,b,c)->{requests++;throw new InterruptedIOException("Fixture connection interrupted");});try{w.run(id);fail();}catch(InterruptedIOException expected){}assertEquals(1,requests);assertEquals(1,w.items(id,"uncertain"));SummaryWork.clients=()->new SeekyAiClient((p,k,b,c)->{requests++;return reply("Não deve repetir automaticamente.");});w.run(id);assertEquals(1,requests);assertEquals(1,w.items(id,"uncertain"));try(TaskStore db=new TaskStore(w.app)){assertTrue(db.job(id).s("message").contains("interrompidos"));}}
    @Test public void completedSummaryPublishesAnAnchoredStudyNoteAndItsExactSource()throws Exception{String id=job(2,2);w.run(id);try(TaskStore work=new TaskStore(w.app);StudyStore notes=new StudyStore(w.app)){StudyStore.Row item=work.items(id,"done",0,1).get(0);String original=SummaryWork.text(w.app,id,item);assertTrue(original.contains("Parágrafo 0"));StudyStore.Row note=notes.rows("notes",null,null,null,1).get(0);assertTrue(note.s("body").contains("Resumo 1"));assertTrue(note.s("body").contains("Texto fornecido"));assertTrue(note.n("material")>0);assertEquals(0,note.n("segment"));}}
    @Test public void publicationAfterAnInterruptionDoesNotDuplicateExistingNotes()throws Exception{String id=job(2,2);w.run(id);try(TaskStore db=new TaskStore(w.app)){StudyStore.Row item=db.items(id,"done",0,1).get(0);SummaryWork.publish(w.app,id,db,db.payload(id),item);SummaryWork.publish(w.app,id,db,db.payload(id),item);}try(StudyStore notes=new StudyStore(w.app)){assertEquals(1,notes.count("notes",null,null));}assertEquals(1,requests);}
    @Test public void unconfirmedNetworkFailureCannotBeAutomaticallySentAgain()throws Exception{String id=job(1,2);SummaryWork.clients=()->new SeekyAiClient((p,k,b,c)->{requests++;throw new IOException("Resposta perdida após enviar.");});try{w.run(id);fail();}catch(IOException expected){}assertEquals(1,w.items(id,"uncertain"));try(TaskStore db=new TaskStore(w.app)){db.retryFailed(id);}w.run(id);assertEquals(1,requests);assertEquals(1,w.items(id,"uncertain"));}
    @Test public void aRejectedRequestCanBeRetriedAsAFailedItem()throws Exception{String id=job(1,2);SummaryWork.clients=()->new SeekyAiClient((p,k,b,c)->{requests++;throw new SeekyAiClient.HttpFailure(400,"Pedido recusado.");});try{w.run(id);fail();}catch(IOException expected){}assertEquals(1,w.items(id,"failed"));assertEquals(0,w.items(id,"uncertain"));}
    @Test public void partialResponsesKeepTheirWarningInThePublishedNote()throws Exception{String id=job(1,2);SummaryWork.clients=()->new SeekyAiClient((p,k,b,c)->reply("Resposta com limite.").replace("STOP","MAX_TOKENS"));w.run(id);try(StudyStore notes=new StudyStore(w.app)){assertTrue(notes.rows("notes",null,null,null,1).get(0).s("body").contains("Resposta parcial do serviço."));}}
}
